{
  "description": "The creature is a quadrupedal, bear-bodied animal shown in right-facing profile against a plain light background. It has dense, shaggy brown fur on its head, neck, legs, and rear, with a broad bear-like muzzle and a short furry tail. Most of its torso, back, and sides are covered by a glossy, dark brown to black segmented exoskeleton that looks like a beetle's carapace, with large smooth dorsal plates, smaller overlapping side plates bearing rows of circular openings, and paler segmented plates on the underside. A single long, shiny black, sickle-shaped horn with a small pointed tooth on its inner curve rises from the top of the head and arches up and backward then forward to a sharp tip.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a brown bear head with thick fur, a lighter tan muzzle, a large dark nose, small dark brown eyes, and whiskers, facing to the right at the front of the body",
      "where": "at the anterior end of the body, attached to the furry neck in front of the dark neck plates"
    },
    {
      "part": "horns",
      "looks_like": "a single long, glossy black, smooth, strongly curved horn tapering to a sharp point, with a small triangular tooth projecting from the inner curve",
      "where": "emerging from the midline of the forehead on top of the head and arching upward and backward over the head"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, furry brown ears with darker interior fur",
      "where": "on the top sides of the head, one on each side of the horn base, behind the horn"
    },
    {
      "part": "legs",
      "looks_like": "four thick, heavily furred brown legs with long shaggy hair, two forelegs and two hindlegs",
      "where": "under the torso, supporting the body, with forelegs under the chest plates and hindlegs under the rear shell"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws with brown fur and five dark, curved claws on each paw",
      "where": "at the distal ends of the four legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a short, bushy, brown furry tail",
      "where": "at the posterior end of the body, protruding from beneath the rear edge of the dark dorsal shell"
    },
    {
      "part": "shell",
      "looks_like": "a glossy, hard, dark brown-black exoskeleton covering the back, shoulders, neck, and sides, with a highly reflective smooth surface",
      "where": "over the dorsal and lateral torso from the neck to the rump, and wrapping around the lower sides and chest"
    },
    {
      "part": "plates",
      "looks_like": "segmented overlapping plates: large transverse glossy bands across the back, smaller side plates with two rows of oval holes with light rims, and paler beige ventral plates with segmented ridges and small dark slits",
      "where": "forming the shell on the back, the mid-flank with holes, and the belly and lower chest"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
